problem_statement:
Consider supporting FIFO + message keys
Firstly, this project is real neat.

Any thoughts on supporting FIFO queues with message key values, similar to SQS FIFO + MessageGroupId ?

Riffing off your existing work, here are the prototype functions which illustrate the idea:

```
CREATE TYPE message_record AS (
    msg_id BIGINT,
    read_ct INTEGER,
    enqueued_at TIMESTAMP WITH TIME ZONE,
    vt TIMESTAMP WITH TIME ZONE,
    group_id UUID,
    message JSONB
);

CREATE FUNCTION create_queue(queue_name TEXT)
RETURNS void AS $$
BEGIN

  EXECUTE FORMAT(
    $QUERY$
    CREATE TABLE IF NOT EXISTS %s (
        msg_id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
        read_ct INT DEFAULT 0 NOT NULL,
        enqueued_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
        vt TIMESTAMP WITH TIME ZONE NOT NULL,
        group_id UUID NOT NULL,
        message JSONB NOT NULL
    )
    $QUERY$,
    queue_name
  );

  EXECUTE FORMAT(
    $QUERY$
    CREATE INDEX IF NOT EXISTS %s_vt_idx ON %s (vt ASC);
    $QUERY$,
    queue_name, queue_name
  );

  EXECUTE FORMAT(
    $QUERY$
    CREATE INDEX IF NOT EXISTS %s_group_id_order ON %s (group_id, msg_id);
    $QUERY$,
    queue_name, queue_name
  );

END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION enqueue(
    queue_name TEXT,
    group_id UUID,
    msg JSONB,
    delay INTEGER DEFAULT 0
) RETURNS SETOF BIGINT AS $$
DECLARE
    sql TEXT;
BEGIN
    sql := FORMAT(
        $QUERY$
        INSERT INTO %s (vt, group_id, message)
        VALUES ((clock_timestamp() + interval '%s seconds'), '%s'::uuid, $1)
        RETURNING msg_id;
        $QUERY$,
        queue_name, delay, group_id
    );
    RETURN QUERY EXECUTE sql USING msg;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION dequeue(
    queue_name TEXT,
    vt INTEGER,
    qty INTEGER
)
RETURNS SETOF message_record AS $$
DECLARE
    sql TEXT;
BEGIN
    sql := FORMAT(
        $QUERY$

        WITH cte0 AS 
        (
          SELECT group_id, MIN(msg_id) AS msg_id
          FROM %s
          GROUP BY group_id
        ),
        cte1 AS
        (
          SELECT t1.msg_id AS msg_id
          FROM %s AS t1
          JOIN cte0 AS t2
            ON t1.group_id = t2.group_id
            AND t1.msg_id = t2.msg_id
          WHERE vt <= clock_timestamp()
          ORDER BY msg_id ASC
          LIMIT $1
          FOR UPDATE SKIP LOCKED
        )

        UPDATE %s m
        SET
            vt = clock_timestamp() + interval '%s seconds',
            read_ct = read_ct + 1
        FROM cte1
        WHERE m.msg_id = cte1.msg_id
        RETURNING m.msg_id, m.read_ct, m.enqueued_at, m.vt, m.group_id, m.message;
        $QUERY$,
        queue_name, queue_name, queue_name, vt
    );
    RETURN QUERY EXECUTE sql USING qty;
END;
$$ LANGUAGE plpgsql;
```

```
SELECT * FROM create_queue('test');

-- Two enqueued messages with the same group id. These should respect FIFO rules.
SELECT * FROM enqueue('test', '0470da73-c6a4-4273-aa31-f48b05555539', '{"email-address": "john.homeowner-1@yopmail.com"}');
SELECT * FROM enqueue('test', '0470da73-c6a4-4273-aa31-f48b05555539', '{"email-address": "john.homeowner-1@yopmail.com", "phone-number": 5551112222}');

-- Third enqueued message with different group id.
SELECT * FROM enqueue('test', gen_random_uuid(), '{"email-address": "john.homeowner-2@yopmail.com}");

-- This should return message id 1 and 3. Message id 2 will NOT be available until 1 has been deleted.
SELECT * FROM dequeue('test', 5, 5);
```

Thoughts?

Difference between tests and doc for FIFO read
I think I’ve identified a conflict between the documentation and the actual implementation of the FIFO grouped read features.

**Documentation Behavior:** The documentation suggests that `read_grouped` retrieves only one message by group
```
-- Send messages to the same FIFO group
select pgmq.send('my_queue', '{"order": 1}', '{"x-pgmq-group": "user123"}');
select pgmq.send('my_queue', '{"order": 2}', '{"x-pgmq-group": "user123"}');
select pgmq.send('my_queue', '{"order": 1}', '{"x-pgmq-group": "user456"}');

-- Read with FIFO RR ordering - interleaves by group layers
select * from pgmq.read_grouped_rr('my_queue', 10, 5);
 msg_id | read_ct |          enqueued_at          |              vt               |     message     |           headers
--------+---------+-------------------------------+-------------------------------+-----------------+---------------------------
      1 |       1 | 2023-10-28 19:14:47.356595-05 | 2023-10-28 19:17:08.608922-05 | {"order": 1}   | {"x-pgmq-group": "user123"}
      3 |       1 | 2023-10-28 19:14:47.356595-05 | 2023-10-28 19:17:08.608974-05 | {"order": 1}   | {"x-pgmq-group": "user456"}
```

**Observed Behavior (Tests/Usage):** In practice and within the test suite, the function retrieves multiple messages from the same group (with round robin or not, according to function).
This behavior means we retrieve messages in batch, not respecting strictly the FIFO strict order described in documentation.
```
-- Send messages to the same FIFO group
select pgmq.send('my_queue', '{"order": 1}', '{"x-pgmq-group": "user123"}');
select pgmq.send('my_queue', '{"order": 2}', '{"x-pgmq-group": "user123"}');
select pgmq.send('my_queue', '{"order": 1}', '{"x-pgmq-group": "user456"}');

-- Read with FIFO RR ordering - interleaves by group layers
select * from pgmq.read_grouped_rr('my_queue', 10, 5);
 msg_id | read_ct |          enqueued_at          |              vt               |     message     |           headers
--------+---------+-------------------------------+-------------------------------+-----------------+---------------------------
      1 |       1 | 2023-10-28 19:14:47.356595-05 | 2023-10-28 19:17:08.608922-05 | {"order": 1}   | {"x-pgmq-group": "user123"}
      3 |       1 | 2023-10-28 19:14:47.356595-05 | 2023-10-28 19:17:08.608974-05 | {"order": 1}   | {"x-pgmq-group": "user456"}
      2 |       1 | 2023-10-28 19:14:47.356595-05 | 2023-10-28 19:17:08.608974-05 | {"order": 2}   | {"x-pgmq-group": "user123"}
```




If I have misunderstood the intended behavior, please let me know where my logic diverges from the design.

